//! **task-11 小格批的运行期抽例**（第 406 轮）——两侧逐行一致。
//!
//! 覆盖：① `dir`（只钉两侧确实一致的观察面：我们内建类型的方法走 `getattr` 槽、
//! **不进类型字典** ✗ ⇒ `dir(str)` 的面与参照不同，抽例只钉“排序／含已登记名字”这些）；
//! ② `_operator._compare_digest`／`hmac`／`secrets`；③ 生成器表达式自由变量（先前**编译期 panic**）；
//! ④ 类体内联推导式（`__classdict__` cell 槽错位）；附带 pow 三参／类型级 `int.bit_length`／
//! `float.fromhex`／`bytes(生成器)`／`itertools.groupby` 与本轮修的**延迟常量下标加宽**回归。
//!
//! 期望输出由本机 `python3`（3.14.4）跑**同一段脚本**取得（不是手写 ✓）。

fn run(name: &str, script: &str) -> String {
    let root = std::env::temp_dir().join(format!("pyawa-small-gaps-{}-{name}", std::process::id()));
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(&root).expect("建临时目录");
    let path = root.join("probe.py");
    std::fs::write(&path, script).expect("写脚本");
    let output = std::process::Command::new(env!("CARGO_BIN_EXE_pyawa"))
        .arg(&path)
        .current_dir(&root)
        .output()
        .expect("跑 CLI");
    let _ = std::fs::remove_dir_all(&root);
    assert!(
        output.status.success(),
        "不许中止（退出状态 {:?}）\n--- stdout ---\n{}\n--- stderr ---\n{}",
        output.status,
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8_lossy(&output.stdout).into_owned()
}

/// 参照（`python3` 3.14 实测 ✓，逐行）。
const EXPECTED: &str = "dir_module True True True\ndir_class True True True\ndir_instance True True True\ndir_int True True True\ndir_module_obj True True True\ndigest True False\ndigest_error unsupported operand types(s) or combination of types: 'int' and 'int'\nhmac True False\nsecrets False\ngenexpr_freevar {1: 1, 2: 0, 3: 1} {1: 0, 2: 1, 3: 0} (2, 1)\ngenexpr_assign {1: 1, 2: 1, 3: 0}\nclass_comprehension [0, 2, 4, 6] [10, 11] [0, 1, 2] 37\npow_mod 1000000000000000000 2 3 376\nbit_length 8 3\nfromhex 0.4152410118609203 -3.0\nbytes_gen b'\\\\]^_'\ngroupby [(1, [1, 1]), (2, [2]), (3, [3, 3])]\n";

const SCRIPT: &str = "# 小格批（task-11）运行期抽例：期望输出由本机 python3 3.14 跑同一段脚本取得。\n# ① dir：只钉\"两侧确实一致\"的可观察面（我们内建类型的方法走 getattr 槽、不进类型字典 ✗）\nX_MODULE = 7\nnames = dir()\nprint(\"dir_module\", type(names) is list, names == sorted(names), 'X_MODULE' in names)\n\n\nclass Box:\n    size = 3\n\n    def __init__(self, value):\n        self.value = value\n\n    def double(self):\n        return self.value * 2\n\n\nbox = Box(5)\nprint(\"dir_class\", 'size' in dir(Box), 'double' in dir(Box), dir(Box) == sorted(dir(Box)))\nprint(\"dir_instance\", 'value' in dir(box), 'size' in dir(box), dir(box) == sorted(dir(box)))\nprint(\"dir_int\", 'bit_length' in dir(1), 'from_bytes' in dir(int), dir(1) == sorted(dir(1)))\nimport sys as _sys\nprint(\"dir_module_obj\", '__name__' in dir(_sys), 'path' in dir(_sys), dir(_sys) == sorted(dir(_sys)))\n\n# ② _operator._compare_digest / hmac / secrets\nimport _operator\nprint(\"digest\", _operator._compare_digest(\"abc\", \"abc\"), _operator._compare_digest(b\"ab\", b\"ac\"))\ntry:\n    _operator._compare_digest(1, 1)\nexcept TypeError as error:\n    print(\"digest_error\", error)\nimport hmac\nprint(\"hmac\", hmac.compare_digest(\"token\", \"token\"), hmac.compare_digest(b\"x\", b\"y\"))\nimport secrets\nprint(\"secrets\", secrets.compare_digest(\"abc\", \"abd\"))\n\n# ③ 生成器表达式自由变量（先前编译期 panic 的形状）\n\n\nclass Context:\n    def __init__(self, flags, traps):\n        self.flags = dict((s, int(s in flags)) for s in [1, 2, 3])\n        self.traps = dict((t, int(t in traps)) for t in [1, 2, 3])\n\n    def summary(self):\n        return sum(self.flags.values()), sum(self.traps.values())\n\n\ncontext = Context([1, 3], [2])\nprint(\"genexpr_freevar\", context.flags, context.traps, context.summary())\nsignals = [1, 2]\nvalue = dict((s, int(s in signals)) for s in signals + [3])\nprint(\"genexpr_assign\", value)\n\n# ④ 类体里的内联推导式（`__classdict__` cell 槽错位那格）\nclass Calendarish:\n    _months = [i * 2 for i in range(4)]\n    if True:\n        _nested = [j + 10 for j in range(2)]\n    _deep = [k for k in range(3)]\n\n    def __init__(self):\n        self.mine = [q for q in range(2)]\n\n    def total(self):\n        return sum(self._months) + sum(self._nested) + sum(self._deep) + sum(self.mine)\n\n\nc = Calendarish()\nprint(\"class_comprehension\", Calendarish._months, Calendarish._nested, Calendarish._deep, c.total())\n\n# 附带：pow 三参／大整数、int.bit_length 类型级、float.fromhex、bytes(生成器)、groupby\nprint(\"pow_mod\", pow(10, 18, 2305843009213693951), pow(-2, 3, 5), pow(2, -1, 5), pow(2, 100) % 1000)\nprint(\"bit_length\", int.bit_length(255), (5).bit_length())\nprint(\"fromhex\", float.fromhex('0x1.a934f0979a371p-2'), float.fromhex('-0x1.8p1'))\nprint(\"bytes_gen\", bytes((x ^ 0x5C) for x in range(4)))\nfrom itertools import groupby\nprint(\"groupby\", [(key, list(group)) for key, group in groupby([1, 1, 2, 3, 3])])\n";

